//@ProcessingGroup("subscriber")
@Component("subscriber-projector")
public class SubscriberProjector extends SubscriberEntityProjector {
		
	// core constructor
	public SubscriberProjector(ProjectorRegistry registry,
									SubscriberRepository repository,
									QueryUpdateEmitter queryUpdateEmitter ) {
        super(registry, repository);
        this.queryUpdateEmitter = queryUpdateEmitter;
    }	

	/*
     * @param	event CreateSubscriberEvent
     */
    @EventHandler( payloadType=CreateSubscriberEvent.class )
    public void handle( CreateSubscriberEvent event) {
	    LOGGER.info("handling CreateSubscriberEvent - " + event );
	    Subscriber entity = new Subscriber();
            entity.setSubscriberId( event.getSubscriberId() );
            entity.setName( event.getName() );
            entity.setAddress( event.getAddress() );
            entity.setChannel( event.getChannel() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllSubscriber( entity );
    }

    /*
     * @param	event UpdateSubscriberEvent
     */
    @EventHandler( payloadType=UpdateSubscriberEvent.class )
    public void handle( UpdateSubscriberEvent event) {
    	LOGGER.info("handling UpdateSubscriberEvent - " + event );
    	
	    Subscriber entity = new Subscriber();
            entity.setSubscriberId( event.getSubscriberId() );
            entity.setName( event.getName() );
            entity.setAddress( event.getAddress() );
            entity.setAlerts( event.getAlerts() );
            entity.setChannel( event.getChannel() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindSubscriber( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllSubscriber( entity );        
    }
    
    /*
     * @param	event DeleteSubscriberEvent
     */
    @EventHandler( payloadType=DeleteSubscriberEvent.class )
    public void handle( DeleteSubscriberEvent event) {
    	LOGGER.info("handling DeleteSubscriberEvent - " + event );
    	
    	// ------------------------------------------
    	// delete delegation
    	// ------------------------------------------
    	Subscriber entity = delete( event.getSubscriberId() );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllSubscriber( entity );

    }    


    /*
     * @param	event AssignAlertsToSubscriberEvent
     */
    @EventHandler( payloadType=AssignAlertsToSubscriberEvent.class)
    public void handle( AssignAlertsToSubscriberEvent event) {
	    LOGGER.info("handling AssignAlertsToSubscriberEvent - " + event );
	    
	    // ------------------------------------------
    	// delegate to addTo 
    	// ------------------------------------------ 
	    Subscriber entity = addToAlerts(event.getSubscriberId(), event.getAddTo() );
        
    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindSubscriber( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllSubscriber( entity );
    }
    

/*
 * @param	event RemoveAlertsFromSubscriberEvent
 */
@EventHandler( payloadType=RemoveAlertsFromSubscriberEvent.class)
public void handle( RemoveAlertsFromSubscriberEvent event) {
    LOGGER.info("handling RemoveAlertsFromSubscriberEvent - " + event );

    Subscriber entity = removeFromAlerts(event.getSubscriberId(), event.getRemoveFrom() );
    
	// ------------------------------------------
	// emit to subscribers that find one
	// ------------------------------------------    	
    emitFindSubscriber( entity );

	// ------------------------------------------
	// emit to subscribers that find all
	// ------------------------------------------    	
    emitFindAllSubscriber( entity );
}



    /**
     * Method to retrieve the Subscriber via an SubscriberPrimaryKey.
     * @param 	id Long
     * @return 	Subscriber
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Subscriber handle( FindSubscriberQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getSubscriberId() );
    }
    
    /**
     * Method to retrieve a collection of all Subscribers
     *
     * @param	query	FindAllSubscriberQuery 
     * @return 	List<Subscriber> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Subscriber> handle( FindAllSubscriberQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindSubscriber,
 * but only if the id matches
 *
 * @param		entity	Subscriber
 */
	protected void emitFindSubscriber( Subscriber entity ) {
		LOGGER.info("handling emitFindSubscriber" );
		
	    queryUpdateEmitter.emit(FindSubscriberQuery.class,
	                            query -> query.getFilter().getSubscriberId().equals(entity.getSubscriberId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllSubscriber
	 * 
	 * @param		entity	Subscriber
	 */
	protected void emitFindAllSubscriber( Subscriber entity ) {
		LOGGER.info("handling emitFindAllSubscriber" );
		
	    queryUpdateEmitter.emit(FindAllSubscriberQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
	private final QueryUpdateEmitter queryUpdateEmitter;
    private static final Logger LOGGER 	= Logger.getLogger(SubscriberProjector.class.getName());

}
